package com.marsx.pool;

import android.app.*;import android.os.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;

public class PremiumActivity extends Activity{
 static final int BG=Color.rgb(4,5,7),CARD=Color.rgb(15,17,21),ORANGE=Color.rgb(255,112,8),WHITE=Color.rgb(246,246,248),MUTED=Color.rgb(145,149,158),GREEN=Color.rgb(34,210,104),RED=Color.rgb(245,66,83);
 LinearLayout page,nav; TextView state,power,workers,shares,temp,battery,balance; Button start; boolean running=false; long started; Handler timer=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);showSplash();}
 int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 TextView t(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(0,dp(7),0,dp(7));return v;}
 GradientDrawable shape(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp((int)r));g.setStroke(dp(1),Color.rgb(66,42,25));return g;}
 LinearLayout base(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setBackgroundColor(BG);return l;}
 LinearLayout card(){LinearLayout c=base();c.setPadding(dp(18),dp(16),dp(18),dp(16));c.setBackground(shape(CARD,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(10));c.setLayoutParams(p);return c;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.BLACK);b.setTextSize(16);b.setAllCaps(false);b.setBackgroundTintList(ColorStateList.valueOf(ORANGE));return b;}
 TextView logo(){TextView x=t("MARS-X",29,WHITE);x.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);x.setLetterSpacing(.08f);return x;}
 void showSplash(){LinearLayout r=base();r.setGravity(Gravity.CENTER);r.setPadding(dp(30),dp(50),dp(30),dp(40));r.addView(new MarsView(this),new LinearLayout.LayoutParams(-1,dp(300)));TextView l=logo();l.setTextSize(43);l.setGravity(Gravity.CENTER);r.addView(l);TextView q=t("GELECEĞİ BUGÜNDEN KAZAN",14,ORANGE);q.setGravity(Gravity.CENTER);r.addView(q);Button b=btn("HEMEN BAŞLA");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(60));p.setMargins(0,dp(35),0,0);r.addView(b,p);b.setOnClickListener(v->consent());setContentView(r);}
 void consent(){LinearLayout r=base();r.setPadding(dp(28),dp(40),dp(28),dp(28));r.addView(logo());r.addView(t("MARS-X'e Hoş Geldin",27,ORANGE));String[] rows={"◉  Kolay Başla\n     Tek dokunuşla oturumu yönet","◉  Gerçek İstatistik\n     Doğrulanmış havuz verileri","◉  %3 Davet Kazancı\n     Arkadaşlarını davet et","◉  Güvenli ve Şeffaf\n     Kontrol her zaman sende"};for(String s:rows)r.addView(t(s,16,WHITE));CheckBox ok=new CheckBox(this);ok.setText("Koşulları ve gizlilik bildirimini kabul ediyorum");ok.setTextColor(MUTED);r.addView(ok);Button b=btn("KABUL ET VE DEVAM ET");r.addView(b,new LinearLayout.LayoutParams(-1,dp(58)));b.setOnClickListener(v->{if(ok.isChecked())shell();else Toast.makeText(this,"Onay gerekli.",Toast.LENGTH_SHORT).show();});setContentView(r);}
 void shell(){LinearLayout root=base();ScrollView s=new ScrollView(this);page=base();page.setPadding(dp(18),dp(16),dp(18),dp(20));s.addView(page);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setBackgroundColor(Color.rgb(9,10,13));addNav("⌂\nAna Sayfa",0);addNav("⌁\nKazanç",1);addNav("▣\nCüzdan",2);addNav("♧\nDavet",3);addNav("⚙\nAyarlar",4);root.addView(nav);setContentView(root);home();}
 void addNav(String s,int n){Button b=new Button(this);b.setText(s);b.setTextSize(10);b.setTextColor(MUTED);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);nav.addView(b,new LinearLayout.LayoutParams(0,dp(62),1));b.setOnClickListener(v->{if(n==0)home();if(n==1)earn();if(n==2)wallet();if(n==3)invite();if(n==4)settings();});}
 void head(String s){page.removeAllViews();LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.addView(logo(),new LinearLayout.LayoutParams(0,-2,1));h.addView(t("●",18,ORANGE));page.addView(h);page.addView(t(s,14,ORANGE));}
 void home(){head("POOL BETA");LinearLayout b=card();b.addView(t("MEVCUT KAZANÇ",12,MUTED));balance=t("0.000000 MARS-X",31,WHITE);b.addView(balance);b.addView(t("Sağlayıcı doğrulaması ile güncellenir",12,GREEN));page.addView(b);LinearLayout c=card();state=t("● HAZIR",15,MUTED);c.addView(state);c.addView(new MarsView(this),new LinearLayout.LayoutParams(-1,dp(250)));start=btn("BAŞLAT");c.addView(start,new LinearLayout.LayoutParams(-1,dp(58)));start.setOnClickListener(v->toggle());page.addView(c);statsCard();}
 void statsCard(){LinearLayout s=card();s.addView(t("GÜÇ VE PERFORMANS",18,WHITE));LinearLayout row=new LinearLayout(this);power=metric(row,"Güç","— Sol/s");workers=metric(row,"Aktif Worker","—");s.addView(row);LinearLayout row2=new LinearLayout(this);shares=metric(row2,"Paylaşılan İş","—");temp=metric(row2,"Sıcaklık","43°C sınır");s.addView(row2);battery=t("Pil alt limiti  %15     •     Ağ durumu  Bekleniyor",13,MUTED);s.addView(battery);Button g=btn("GELİŞMİŞ GRAFİKLER");g.setOnClickListener(v->graphs());s.addView(g);page.addView(s);}
 TextView metric(LinearLayout r,String a,String b){LinearLayout c=base();c.setPadding(dp(10),dp(8),dp(10),dp(8));c.setBackground(shape(Color.rgb(20,22,27),14));c.addView(t(a,11,MUTED));TextView v=t(b,17,WHITE);c.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(75),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));r.addView(c,p);return v;}
 void toggle(){running=!running;if(running)started=System.currentTimeMillis();state.setText(running?"● OTURUM AKTİF":"● DURDURULDU");state.setTextColor(running?GREEN:MUTED);start.setText(running?"DURDUR":"BAŞLAT");}
 void earn(){head("KAZANÇ İSTATİSTİKLERİ");LinearLayout c=card();c.addView(t("Günlük     Haftalık     Aylık     Tümü",14,ORANGE));c.addView(t("0.000000 MARS-X",31,WHITE));c.addView(new ChartView(this),new LinearLayout.LayoutParams(-1,dp(210)));page.addView(c);LinearLayout r=new LinearLayout(this);metric(r,"Ortalama/Saat","—");metric(r,"En Yüksek","—");page.addView(r);LinearLayout r2=new LinearLayout(this);metric(r2,"Toplam Süre","—");metric(r2,"Aktif Oturum",running?"Aktif":"Kapalı");page.addView(r2);history();}
 void graphs(){head("GRAFİKLER");LinearLayout c=card();c.addView(t("Kazanç     Cihaz     Ağ     Sıcaklık",14,ORANGE));c.addView(new ChartView(this),new LinearLayout.LayoutParams(-1,dp(220)));c.addView(t("Doğrulanmış veri geldikçe grafik otomatik çizilir.",13,MUTED));page.addView(c);LinearLayout d=card();d.addView(t("HAFTALIK KAZANÇ DAĞILIMI",17,WHITE));d.addView(new BarView(this),new LinearLayout.LayoutParams(-1,dp(180)));page.addView(d);}
 void history(){LinearLayout h=card();h.addView(t("İŞLEM GEÇMİŞİ",18,WHITE));h.addView(t("Henüz doğrulanmış işlem yok",14,MUTED));page.addView(h);}
 void wallet(){head("CÜZDAN");LinearLayout c=card();c.addView(t("TOPLAM BAKİYE",12,MUTED));c.addView(t("0.000000 MARS-X",32,WHITE));c.addView(t("Beta içi doğrulanmış kazanç",12,ORANGE));page.addView(c);LinearLayout a=new LinearLayout(this);metric(a,"Gönder","Coming Soon");metric(a,"Çekim","Coming Soon");page.addView(a);history();}
 void invite(){head("DAVET ET KAZAN");LinearLayout c=card();TextView i=t("● ● ●",44,ORANGE);i.setGravity(Gravity.CENTER);c.addView(i);TextView x=t("Arkadaşlarını Davet Et",22,WHITE);x.setGravity(Gravity.CENTER);c.addView(x);TextView p=t("Her uygun davet için\n+%3 kazanç bonusu",24,ORANGE);p.setGravity(Gravity.CENTER);c.addView(p);Button b=btn("PAYLAŞ — BETA");b.setOnClickListener(v->{Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/plain");in.putExtra(Intent.EXTRA_TEXT,"MARS-X Pool Beta");startActivity(Intent.createChooser(in,"Paylaş"));});c.addView(b);page.addView(c);}
 void settings(){head("AYARLAR");LinearLayout c=card();String[] a={"Hesap Bilgileri                         ›","Bildirimler                              ›","Tema                         Mars Turuncu ›","Dil                              Türkçe ›","Güç Ayarları                            ›","Pil Optimizasyonu                 %15 ›","Sıcaklık Kontrolü                 43°C ›","Veri Kullanımı                          ›","Güvenlik                                ›","Hakkında                         v1.0.0 ›"};for(String s:a)c.addView(t(s,15,WHITE));page.addView(c);}
 public static class MarsView extends View{Paint p=new Paint(1);public MarsView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.48f,r=Math.min(w,h)*.31f;p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx-r*.3f,cy-r*.35f,r*1.4f,new int[]{Color.rgb(255,151,55),Color.rgb(181,54,12),Color.rgb(40,8,5)},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(5,w*.018f));p.setColor(ORANGE);RectF o=new RectF(cx-r*1.35f,cy-r*.45f,cx+r*1.35f,cy+r*.45f);c.save();c.rotate(-18,cx,cy);c.drawOval(o,p);c.restore();p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(90,0,0,0));c.drawCircle(cx+r*.28f,cy-r*.16f,r*.13f,p);c.drawCircle(cx-r*.25f,cy+r*.2f,r*.09f,p);}}
 public static class ChartView extends View{Paint p=new Paint(1);public ChartView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStrokeWidth(1);p.setColor(Color.rgb(36,40,45));for(int i=1;i<5;i++)c.drawLine(0,h*i/5,w,h*i/5,p);p.setColor(ORANGE);p.setStrokeWidth(5);Path q=new Path();q.moveTo(0,h*.75f);for(int i=1;i<=12;i++){float x=w*i/12f;float y=h*(.72f-(i%4)*.025f);q.lineTo(x,y);}c.drawPath(q,p);p.setColor(Color.argb(35,255,112,8));q.lineTo(w,h);q.lineTo(0,h);q.close();c.drawPath(q,p);}}
 public static class BarView extends View{Paint p=new Paint(1);public BarView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(ORANGE);for(int i=0;i<7;i++){float bw=w/12f,x=w*(i+1)/8f;float bh=h*(.15f+.04f*(i%3));c.drawRoundRect(x-bw/2,h-bh,x+bw/2,h,8,8,p);}}}
}